 result=p.evaluate("""async info=>{const d=await import('./js/db.js'),r=await import('./js/remote-approved-db.js'),cost=await import('./js/cost-review-db.js'),ec=await import('./js/enterprise-core.js'),pay=await import('./js/payroll-core.js');const data=await d.dumpAll();data.attachments=await d.getAll('attachments');if(data.fuel_records.length!==1||data.cash_records.length!==1||data.payables.length!==1||data.attachments.length!==1)throw Error('wrong native counts');const f=data.fuel_records[0],cash=data.cash_records[0],bill=data.payables[0],photo=data.attachments[0];if(f.total!==27||f.liters!==2||f.receipt!=='Hayır'||f.kdv_rate!==null||cash.source_id!==f.id||cash.amount!==27||f.cash_record_id!==cash.id)throw Error('fuel/cash mismatch');if(bill.gross_total!==91||!bill.kdv_unknown||photo.record_type!=='payable'||photo.record_id!==bill.id||!photo.blob.size||!photo.src_sha256)throw Error('bill/photo mismatch');if(ec.billBalance(bill,[]).remaining!==91||ec.costLedger(data).reduce((s,x)=>s+x.gross,0)!==118||ec.costLedger(data).some(x=>x.known_tax))throw Error('duplicate or fake tax cost');for(const s of ['expense_records','supplier_payments','bank_movements','fuel_tank_movements','personnel_events','cari_movements'])if(data[s].length)throw Error('unexpected write '+s);if(pay.payrollFor(data,data.personnel[0],'2026-01').reimb!==0)throw Error('employee claim invented');for(const [store,rec,delta]of [['fuel_records',f,{total:28}],['cash_records',cash,{amount:28}]]){let locked=false;try{await d.saveExisting(store,rec,delta,'TEST single-side edit145')}catch(e){locked=e.code==='FINANCE_LOCKED'}if(!locked)throw Error('linked financial edit not guarded');}const snap=async()=>JSON.stringify({data:await d.dumpAll(),meta:await d.getAll('meta'),attachments:await Promise.all((await d.getAll('attachments')).map(async a=>({...a,bytes:Array.from(new Uint8Array(await a.blob.arrayBuffer()))})))}),before=await snap();for(const p of [info.fuel,info.credit]){const ack=await r.commitApprovedPacket(p,info.channel);if(!ack.replayed||ack.status!=='saved')throw Error('missing saved receipt');}if(await snap()!==before)throw Error('replay changed records');const conflict=structuredClone(info.fuel);conflict.row.description+=' changed';let conflicted=false;try{await r.commitApprovedPacket(conflict,info.channel)}catch(e){conflicted=e.code==='OP_CONFLICT'}if(!conflicted)throw Error('conflict bypass');const next=structuredClone(info.credit);next.id=crypto.randomUUID();next.row.source_key='TEST rollback145';next.row.date='2026-01-04';next.row.amount=93;await r.commitApprovedPacket(next,info.channel);const canvas=document.createElement('canvas');canvas.width=2;canvas.height=2;const cx=canvas.getContext('2d');cx.fillStyle='red';cx.fillRect(0,0,2,2);const differentPhoto=await new Promise(ok=>canvas.toBlob(ok,'image/png'));const rb=await snap(),add=IDBObjectStore.prototype.add;let rolled=false;IDBObjectStore.prototype.add=function(v,...args){if(this.name==='meta'&&v.key?.startsWith('remote-approved:'))throw Error('TEST atomic rollback145');return add.call(this,v,...args);};try{await cost.saveCostReview(next.id,{confirmed:true,amount:93},{localApproval:true,canWrite:()=>true,file:new File([differentPhoto],'TEST-other145.png',{type:'image/png'})})}catch(e){rolled=e.message.includes('TEST atomic rollback145')}finally{IDBObjectStore.prototype.add=add}if(!rolled||await snap()!==rb)throw Error('partial bill/photo/receipt write');return {fuel:1,cash:1,payable:1,photo:1,unknown_vat:true,local_save:true,no_employee_claim:true,no_duplicate_expense:true,replay:true,conflict:conflicted,atomic:rolled};}""",info)
